import json

ALLOWED_ACTIONS = {"resumer", "traduire", "classer"}
MAX_LENGTH = 500

def validate(raw: str) -> dict:
    data = json.loads(raw)
    if not isinstance(data, dict) or set(data) != {"action", "texte"}:
        raise ValueError("champs inattendus")
    if data["action"] not in ALLOWED_ACTIONS:
        raise ValueError("action non autorisée")
    if not isinstance(data["texte"], str) or len(data["texte"]) > MAX_LENGTH:
        raise ValueError("texte invalide")
    return data

examples = [
    '{"action": "resumer", "texte": "Un texte court."}',
    '{"action": "supprimer", "texte": "x"}',
]

for raw in examples:
    try:
        print("accepté", validate(raw))
    except ValueError as exc:
        print("refusé", exc)
